"""Generates Bazel crate annotations from third_party/rust_crates/Cargo.toml.

This script parses [gn.package] annotations in Cargo.toml (treating Cargo.toml
as the single source of truth for crate rustc flags, environments, and versions)
and translates them into Starlark annotations for Bazel's crates_vendor rule.
It also validates crate_annotation_overwrites.bzl to prevent version drift.
"""

import argparse
import os
import subprocess
import sys
import tomllib
from dataclasses import dataclass
from typing import Any, Union

# The expected variable name in the crate annotation overwrites .bzl file.
_ANNOTATION_OVERWRITES_DICT_NAME = "CRATE_ANNOTATION_OVERWRITES"

# Maps GN target OS/arch strings to Bazel platform labels.
_PLATFORM_MAP = {
    'cfg(target_os = "linux")': "@platforms//os:linux",
    'cfg(target_os = "macos")': "@platforms//os:macos",
    'cfg(target_os = "freebsd")': "@platforms//os:freebsd",
    'cfg(target_os = "fuchsia")': "@platforms//os:fuchsia",
    'cfg(target_arch = "x86_64")': "@platforms//cpu:x86_64",
}

# Crates whose Cargo.toml [gn.package] annotations are GN-specific workarounds
# that conflict with rules_rust's native cargo_build_script execution in Bazel.
_EXCLUDED_CRATES = {
    "rustix",
}

_STARLARK_FILE_TEMPLATE = """# Copyright 2025 The Fuchsia Authors. All rights reserved.
# Use of this source code is governed by a BSD-style license that can be
# found in the LICENSE file.

# AUTO-GENERATED - DO NOT EDIT.
#
# This file contains annotations for third-party Rust crates. These are extra
# field values (e.g. rustc_flags, features, deps, etc.), sometimes
# environment-specific, added to default generated values.
#
# Generated by //build/bazel/update-rustc-third-party/generate_crate_annotations.py
# from GN annotations in //third_party/rust_crates/Cargo.toml.
#
# For Bazel-specific overwrites, see
# //build/bazel/update-rustc-third-party/crate_annotation_overwrites.bzl.
#
# To update this file, run:
#
#   fx update-rustc-third-party
#

load("@rules_rust//crate_universe:defs.bzl", "crate")

CRATE_ANNOTATIONS = {{
{crate_entries}
}}
"""


@dataclass
class CrateConfig:
    """Configuration for a specific version of a crate extracted from Cargo.toml."""

    rustflags: list[str]
    env_vars: dict[str, str]
    platform_configs: dict[str, list[str]]


# Represents parsed data from [gn.package] configs in Cargo.toml.
# The outer dictionary key is the package name (e.g. "serde").
# The inner dictionary key is the package version (e.g. "1.0.197").
CargoTomlData = dict[str, dict[str, CrateConfig]]


# Represents the types allowed for values within a crate.annotation() Starlark block.
# - bool, str, list[str], dict[str, str] are standard literal types.
# - "CrateSelect" is our Python object representing the resolved `crate.select(...)` function.
CrateAttribute = Union[
    bool, str, list[str], dict[str, str], dict[str, list[str]], "CrateSelect"
]


@dataclass
class BazelCrateAnnotation:
    """Represents a Bazel crate annotation.

    Attributes:
        version: The exact version string (or '*' for wildcard) this annotation applies to.
        attributes: The remaining Bazel attributes (e.g. rustc_flags, deps). The dictionary keys
            represent the named argument names for `crate.annotation(key=value)`.
    """

    version: str
    attributes: dict[str, CrateAttribute]


class CrateSelect:
    """Mock object used to capture the state of a parsed `crate.select(...)` Starlark function call."""

    def __init__(
        self,
        common: list[str],
        selects: dict[str, list[str]],
    ) -> None:
        self.common = common
        self.selects = selects


class Crate:
    """Mock API class bound to the `crate` variable during our Python-based Starlark `.bzl` evaluation."""

    @staticmethod
    def select(
        common: list[str] | None = None,
        selects: dict[str, list[str]] | None = None,
    ) -> CrateSelect:
        return CrateSelect(common=common or [], selects=selects or {})

    @staticmethod
    def annotation(**kwargs: Any) -> BazelCrateAnnotation:
        version = kwargs.pop("version")
        return BazelCrateAnnotation(version=version, attributes=kwargs)


def parse_annotation_overwrites(
    path: str,
) -> dict[str, list[BazelCrateAnnotation]]:
    """Evaluates the given Starlark (.bzl) file in memory and extracts its annotations dictionary.

    Rather than requiring a full Starlark lexer, this uses a trick: Bazel's `.bzl` syntax maps
    almost 1:1 with Python. By executing the file directly using `exec()` within a strictly
    controlled local namespace, we can substitute our own Python mock objects in place of Bazel APIs,
    allowing us to easily unpack the Starlark variable assignments into standard Python dictionaries
    and custom dataclasses.
    """
    crate_mod = Crate()
    # We evaluate the .bzl file as Python code. To prevent it from polluting our
    # module's globals and to inject Bazel built-in functions (like `crate`), we
    # pass a specific dictionary as the namespace for the `exec` call.
    local_env: dict[str, Any] = {
        "crate": crate_mod,
        # Bazel's load() doesn't exist in Python. To parse the Starlark (.bzl)
        # file securely as simple Python using exec(), we override "load" with
        # a no-op lambda so the script doesn't crash on standard Bazel load statements.
        "load": lambda *args, **kwargs: None,
    }
    with open(path, "r") as f:
        exec(f.read(), local_env)
    return local_env.get(_ANNOTATION_OVERWRITES_DICT_NAME, {})


def is_gn_specific_env_var(key: str, value: str) -> bool:
    """Determines whether an environment variable is GN-specific and should be skipped for Bazel.

    GN-specific template variables like '${gn_source_root}' and variables like
    'CARGO_MANIFEST_DIR' or 'OUT_DIR' are either invalid in Bazel syntax or interfere
    with rules_rust's cargo_build_script sandboxing.

    Args:
        key: The environment variable name (e.g. "OUT_DIR").
        value: The environment variable value (e.g. "${gn_source_root}/...").

    Returns:
        True if the variable is GN-specific and should be omitted from Bazel
        annotations; False otherwise.
    """
    return "${gn_source_root}" in value or key in (
        "CARGO_MANIFEST_DIR",
        "OUT_DIR",
    )


def parse_cargo_toml(
    cargo_toml_path: str,
) -> CargoTomlData:
    """Parses Cargo.toml and returns package configurations and active versions.

    Args:
        cargo_toml_path: Path to third_party/rust_crates/Cargo.toml.

    Returns:
        A CargoTomlData containing gn_packages mapping.
    """
    with open(cargo_toml_path, "rb") as f:
        data = tomllib.load(f)

    gn_packages = data.get("gn", {}).get("package", {})

    def _unescape_gn_string(v: Any) -> Any:
        """Unescapes double-quoted strings from GN metadata strings in Cargo.toml.

        GN string interpolation outputs literal backslashes out of necessity.
        This function recursively strips those backslashes to resolve the actual
        string values for use in Bazel annotations (e.g. `\"value\"` becomes `"value"`).
        """
        if isinstance(v, str):
            return v.replace('\\"', '"')
        if isinstance(v, list):
            return [_unescape_gn_string(x) for x in v]
        if isinstance(v, dict):
            return {k: _unescape_gn_string(val) for k, val in v.items()}
        return v

    unescaped_packages = _unescape_gn_string(gn_packages)
    packages: dict[str, dict[str, CrateConfig]] = {}
    for pkg_name, pkg_data in unescaped_packages.items():
        packages[pkg_name] = {}
        for version, cfg in pkg_data.items():
            platform_configs: dict[str, list[str]] = {}
            for plat_cfg, plat_data in cfg.get("platform", {}).items():
                platform_configs[plat_cfg] = list(
                    plat_data.get("rustflags", [])
                )
            packages[pkg_name][version] = CrateConfig(
                rustflags=list(cfg.get("rustflags", [])),
                env_vars=parse_env_vars(cfg.get("env_vars", [])),
                platform_configs=platform_configs,
            )

    return packages


def parse_env_vars(env_var_list: list[str]) -> dict[str, str]:
    """Converts a list of 'KEY=VALUE' strings into a dictionary.

    Filters out GN-specific environment variables that are invalid in Bazel
    or managed natively by rules_rust.

    Args:
        env_var_list: A list of environment variable definitions in "KEY=VALUE" format.

    Returns:
        A dictionary mapping environment variable names to their values.
    """
    env_dict: dict[str, str] = {}
    for entry in env_var_list:
        if "=" not in entry:
            raise ValueError(
                f"Invalid env var format '{entry}'. Expected 'KEY=VALUE'."
            )
        k, v = entry.split("=", 1)
        if not is_gn_specific_env_var(k, v):
            env_dict[k] = v
    return env_dict


def filter_bazel_platform_flags(
    plat_cfg: str,
    plat_flags: list[str],
) -> tuple[list[str], dict[str, list[str]]]:
    """Maps GN platform configurations to their Bazel equivalents.

    This maps the target OS and architecture configurations defined in GN/Cargo.toml
    to Bazel @platforms target labels or extends the common flags.

    Args:
        plat_cfg: The GN platform configuration string (e.g. 'cfg(target_os = "linux")').
        plat_flags: The rustc flags associated with this platform.

    Returns:
        A tuple of (common_flags_to_append, platform_flags_dict_to_update).

    Raises:
        ValueError: If the platform configuration is unmapped and not recognized.
    """
    if plat_cfg in _PLATFORM_MAP:
        return [], {_PLATFORM_MAP[plat_cfg]: plat_flags}
    if (
        plat_cfg.startswith('cfg(any(target_arch = "x86_64"')
        or plat_cfg == "cfg(not(kernel))"
    ):
        return plat_flags, {}
    if plat_cfg == 'cfg(not(target_os = "fuchsia"))':
        return [], {"@platforms//os:linux": plat_flags}
    if plat_cfg == "cfg(kernel)":
        # We don't support kernel builds in Bazel currently, so returning empty to drop these flags.
        return [], {}

    raise ValueError(f"unmapped platform cfg '{plat_cfg}'")


def build_crate_annotations(
    gn_packages: dict[str, dict[str, CrateConfig]],
) -> dict[str, list[BazelCrateAnnotation]]:
    """Generates Bazel annotations per package and version from GN configurations.

    Args:
        gn_packages: A dictionary of package configurations parsed from [gn.package]
            in Cargo.toml.

    Returns:
        A dictionary mapping package names to lists of annotation dicts containing
        "version", "common_flags", "platform_flags", and "env_vars".
    """
    annotations: dict[str, list[BazelCrateAnnotation]] = {}

    # Iterate over sorted keys for deterministic generation of annotations.
    for pkg_name in sorted(gn_packages.keys()):
        if pkg_name in _EXCLUDED_CRATES:
            continue

        version_to_cfgs = gn_packages[pkg_name]
        pkg_annotations: list[BazelCrateAnnotation] = []
        # Iterate over sorted versions for deterministic generation of annotations.
        for version, cfg in sorted(version_to_cfgs.items()):
            common_flags = list(cfg.rustflags)
            platform_flags: dict[str, list[str]] = {}
            env_vars = cfg.env_vars

            # Check platform-specific configurations.
            for plat_cfg, plat_flags in cfg.platform_configs.items():
                if not plat_flags:
                    continue
                try:
                    c_flags, p_flags_dict = filter_bazel_platform_flags(
                        plat_cfg, plat_flags
                    )
                    common_flags.extend(c_flags)
                    for k, v in p_flags_dict.items():
                        platform_flags.setdefault(k, []).extend(v)
                except ValueError as e:
                    print(
                        f"Warning: {e} for crate {pkg_name} {version}",
                        file=sys.stderr,
                    )

            # Only generate an annotation if there are rustc flags or env vars.
            if common_flags or platform_flags or env_vars:
                attrs: dict[str, CrateAttribute] = {}
                if common_flags or platform_flags:
                    if platform_flags:
                        attrs["rustc_flags"] = CrateSelect(
                            common=common_flags, selects=platform_flags
                        )
                    else:
                        attrs["rustc_flags"] = common_flags
                if env_vars:
                    attrs["rustc_env"] = env_vars
                pkg_annotations.append(
                    BazelCrateAnnotation(version=version, attributes=attrs)
                )

        if pkg_annotations:
            annotations[pkg_name] = pkg_annotations

    return annotations


def merge_annotations(
    gn_anns: dict[str, list[BazelCrateAnnotation]],
    ann_overwrites: dict[str, list[BazelCrateAnnotation]],
) -> dict[str, list[BazelCrateAnnotation]]:
    """Merges GN-generated annotations with annotation overwrites.

    For each crate, this resolves specific versions tracked by GN and applies
    any overrides from annotation overwrites. Manual annotations specifying version='*'
    will be applied across all specific GN versions of that crate.

    In the event of a conflict (e.g. both GN and Bazel manual overwrites define
    the same list for `rustc_flags` or `rustc_env`), the overwrite completely
    replaces the generated value for that version. Lists and dictionaries are
    not appended or merged together. The dictionary update() applies Bazel manual
    overwrites as the absolute final authority.

    Args:
        gn_annnns: Annotations extracted from Cargo.toml via build_crate_annotations.
        ann_overwrites: Annotations extracted from crate_annotation_overwrites.bzl.

    Returns:
        A merged dictionary mapping crate names to their complete list of BazelCrateAnnotations.
    """
    merged: dict[str, list[BazelCrateAnnotation]] = {}
    all_pkgs = set(gn_anns.keys()).union(set(ann_overwrites.keys()))

    for pkg in all_pkgs:
        gn_pkg_anns = gn_anns.get(pkg, [])
        pkg_ann_overwrites = ann_overwrites.get(pkg, [])

        gn_ann_by_version = {a.version: a for a in gn_pkg_anns}
        ann_overwrite_by_version = {a.version: a for a in pkg_ann_overwrites}

        star_ann_overwrite = ann_overwrite_by_version.get("*")

        all_versions = set(gn_ann_by_version.keys()).union(
            {v for v in ann_overwrite_by_version.keys() if v != "*"}
        )
        merged_anns: list[BazelCrateAnnotation] = []

        if not all_versions and star_ann_overwrite:
            merged_anns.append(star_ann_overwrite)
        else:
            for v in sorted(all_versions):
                gn_ann = gn_ann_by_version.get(v)
                ann_overwrite = ann_overwrite_by_version.get(v)

                merged_attrs: dict[str, CrateAttribute] = {}
                if gn_ann:
                    merged_attrs.update(gn_ann.attributes)
                if star_ann_overwrite:
                    merged_attrs.update(star_ann_overwrite.attributes)
                if ann_overwrite:
                    merged_attrs.update(ann_overwrite.attributes)

                merged_anns.append(
                    BazelCrateAnnotation(version=v, attributes=merged_attrs)
                )

        if merged_anns:
            merged[pkg] = merged_anns

    return merged


def _render_starlark_val(val: CrateAttribute) -> str:
    if isinstance(val, bool):
        return "True" if val else "False"
    if isinstance(val, CrateSelect):
        common = _render_starlark_val(val.common)
        selects = _render_starlark_val(val.selects)
        return f"crate.select(\ncommon = {common},\nselects = {selects},\n)"
    if isinstance(val, (list, set, tuple)):
        if not val:
            return "[]"
        items = ",\n".join(_render_starlark_val(x) for x in val)
        return f"[\n{items},\n]"
    if isinstance(val, dict):
        if not val:
            return "{}"
        items = ",\n".join(
            f"{_render_starlark_val(k)}: {_render_starlark_val(v)}"
            for k, v in val.items()
        )
        return f"{{\n{items},\n}}"
    return repr(val)


def _render_annotation(ann: BazelCrateAnnotation) -> str:
    fields = [f'version = "{ann.version}"']
    for k, v in sorted(ann.attributes.items()):
        fields.append(f"{k} = {_render_starlark_val(v)}")
    fields_str = ",\n".join(fields)
    return f"crate.annotation(\n{fields_str},\n),"


def _render_crate_entry(
    pkg_name: str, pkg_annotations: list[BazelCrateAnnotation]
) -> str:
    rendered_anns = "\n".join(
        _render_annotation(ann) for ann in pkg_annotations
    )
    return f'"{pkg_name}": [\n{rendered_anns}\n],'


def render_starlark(annotations: dict[str, list[BazelCrateAnnotation]]) -> str:
    """Renders the annotations dictionary into Starlark code using templates.

    Args:
        annotations: Mapping of package names to lists of annotation dicts.

    Returns:
        Complete formatted Starlark file content for crate_annotations.bzl.
    """
    crate_entries = "\n".join(
        _render_crate_entry(pkg_name, annotations[pkg_name])
        # Iterate over sorted keys for deterministic output generation.
        for pkg_name in sorted(annotations.keys())
    )
    return _STARLARK_FILE_TEMPLATE.format(crate_entries=crate_entries)


def validate_annotation_overwrites(
    annotation_overwrites: dict[str, list[BazelCrateAnnotation]],
    gn_packages: dict[str, dict[str, Any]],
) -> list[str]:
    """Validates that explicit version strings in crate_annotation_overwrites.bzl still exist in Cargo.toml.

    Args:
        annotation_overwrites: The parsed annotation overwrites dictionary.
        gn_packages: A mapping of package names to version configs parsed from Cargo.toml.

    Returns:
        A list of error messages for stale version annotations found, or an empty list if valid.
    """
    errors: list[str] = []

    for crate_name, anns in annotation_overwrites.items():
        if crate_name not in gn_packages:
            errors.append(
                f"Crate '{crate_name}' in annotation overwrites is missing from Cargo.toml."
            )
            continue

        for ann in anns:
            ver = ann.version
            if not ver or ver == "*":
                continue

            if ver not in gn_packages[crate_name]:
                available = ", ".join(sorted(gn_packages[crate_name].keys()))
                errors.append(
                    f"Crate '{crate_name}' specifies stale version '{ver}' in annotation overwrites. "
                    f"Active version(s) in Cargo.toml: [{available}]. "
                    f"Please update annotation overwrites or use version = '*' if version-agnostic."
                )

    return errors


def main() -> int:
    """Main entry point for generating or checking Bazel crate annotations.

    Returns:
        0 on success, or non-zero on failure.
    """
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument(
        "--cargo-toml",
        required=True,
        help="Path to cargo.toml file to generate annotations from",
    )
    parser.add_argument(
        "--annotation-overwrites",
        required=True,
        help=f"Path to crate_annotation_overwrites.bzl that includes Bazel-specific overwrites. "
        f"Must contain a variable named {_ANNOTATION_OVERWRITES_DICT_NAME}.",
    )
    parser.add_argument(
        "--output",
        required=True,
        help="Path to crate_annotations.bzl output",
    )
    parser.add_argument(
        "--buildifier",
        required=True,
        help="Path to buildifier binary for formatting",
    )
    args = parser.parse_args()

    cargo_data = parse_cargo_toml(args.cargo_toml)

    # Parse annotation overwrites early to validate its entries.
    annotation_overwrites = parse_annotation_overwrites(
        args.annotation_overwrites
    )
    validation_errors = validate_annotation_overwrites(
        annotation_overwrites, cargo_data
    )
    if validation_errors:
        for err in validation_errors:
            print(f"ERROR: {err}", file=sys.stderr)
        return 1

    gn_annnnotations = build_crate_annotations(cargo_data)
    annotations = merge_annotations(gn_annnnotations, annotation_overwrites)
    starlark_content = render_starlark(annotations)

    if not os.path.exists(args.buildifier):
        print(
            f"ERROR: buildifier not found at {args.buildifier}", file=sys.stderr
        )
        return 1

    try:
        proc = subprocess.run(
            [args.buildifier, "-type=bzl"],
            input=starlark_content.encode("utf-8"),
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            check=True,
        )
        starlark_content = proc.stdout.decode("utf-8")
    except subprocess.SubprocessError as e:
        print(
            f"ERROR: buildifier format failed: {e}",
            file=sys.stderr,
        )
        return 1

    with open(args.output, "w", encoding="utf-8") as f:
        f.write(starlark_content)

    return 0


if __name__ == "__main__":
    sys.exit(main())
